// AI generated by GitHub Copilot (DeepSeek V4 Pro), v3.0
bool ImportRunner::store_chunks( const std::vector<DataRecord> & records, ImportResult & result )
{
    for( std::size_t i = 0; i < records.size(); i += m_batch_size ) {
        const std::size_t e = std::min( i + m_batch_size, records.size() );

        const std::vector<DataRecord> chunk( records.begin() + i, records.begin() + e );

        if( !m_sink.store( chunk ) ) {
            return false;
        }

        result.records += chunk.size();
    }

    return true;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v3.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v4.0
bool ImportRunner::flush_day( std::vector<DataRecord> & day_records, ImportResult & result )
{
    if( day_records.empty() ) {
        return true;
    }

    const std::string day = day_records.front().date_str;

    ++result.days;

    const std::size_t records_before   = result.records;
    const std::size_t duplicate_before = result.duplicates;

    std::set<std::string> existing;

    if( !m_sink.existingTimestamps( day, existing ) ) {
        return false;
    }

    std::vector<DataRecord> todo;
    todo.reserve( day_records.size() );

    for( const auto & rec : day_records ) {
        if( existing.count( rec.getRawDateTimeStr() ) ) {
            ++result.duplicates;
            continue;
        }
        todo.push_back( rec );
    }

    if( !store_chunks( todo, result ) ) {
        return false;
    }

    DEBUG( Tools::format( "%s: %ld stored, %ld already present",
                          day.c_str(),
                          (long)( result.records - records_before ),
                          (long)( result.duplicates - duplicate_before ) ) );

    day_records.clear();
    return true;
}
