// AI generated by GitHub Copilot (DeepSeek V4 Pro), v4.0
ImportResult ImportRunner::run( std::streamoff start_offset )
{
    ImportResult result;
    result.start_offset = start_offset;
    result.end_offset   = start_offset;

    CSVUtil csv( m_file );

    if( !csv ) {
        result.ok = false;
        return result;
    }

    // everything up to the last complete line ('\n') may be imported
    const std::streamoff end = complete_file_size( m_file );

    // rsync may write in place while we read: remember the state of the file
    const FileState state_before = file_state( m_file );

    std::vector<DataRecord> day;
    std::string current_day;

    for( CSVUtil::iterator it( &csv, std::fstream::pos_type( start_offset ) );
         it != csv.end(); ++it ) {
        const std::vector<std::string> fields = *it;
        const std::streamoff pos = (std::streamoff)csv.getCurrentPos();

        if( pos >= end ) {
            break;      // trailing partial record, still being written
        }

        ++result.lines;

        if( fields.empty() ) {
            ++result.empty;
            continue;
        }

        if( fields.size() < DataRecord::MAX_FIELDS ) {
            ++result.malformed;
            continue;
        }

        const DataRecord rec( fields );

        if( rec.timestamp == 0 ) {
            ++result.malformed;
            continue;
        }

        if( !current_day.empty() && rec.date_str != current_day ) {
            if( !flush_day( day, result ) ) {
                result.ok = false;
                return result;
            }
        }

        current_day = rec.date_str;
        day.push_back( rec );
    }

    if( !flush_day( day, result ) ) {
        result.ok = false;
        return result;
    }

    if( file_was_modified( state_before, file_state( m_file ) ) ) {
        result.file_changed = true;
        result.ok = false;
    }

    result.end_offset = end > start_offset ? end : start_offset;
    return result;
}
